using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;
public static class F1StoryDiagnose {public static object Run(){return Newtonsoft.Json.JsonConvert.SerializeObject(SceneManager.GetActiveScene().GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Renderer>(true)).Where(r=>r.name.Contains("Floor")||r.sharedMaterials.Any(m=>m&&m.name.Contains("Floor"))).Select(r=>new{r.name,path=AnimationUtility.CalculateTransformPath(r.transform,null),position=r.transform.position.ToString(),bounds=r.bounds.ToString(),active=r.gameObject.activeInHierarchy,materials=r.sharedMaterials.Select(m=>new{m.name,shader=m.shader.name,mode=m.HasProperty("_AE_Mode")?m.GetFloat("_AE_Mode"):-1,path=AssetDatabase.GetAssetPath(m)})}).ToArray());}}
